#!/bin/zsh
cd "$(dirname "$0")"
D="$(pwd)/gen"
S="ESTILO: pixel art de videojuego estilo Pokémon Esmeralda (Game Boy Advance) pero en alta resolución, colores pastel brillantes y muy tiernos, contornos oscuros limpios. SIN texto, SIN letras, SIN números, SIN marcas de agua."
KEY="El FONDO debe ser magenta puro liso (#FF00FF) en toda la imagen, sin degradado, sin sombras en el fondo; cada objeto bien separado con mucho espacio magenta alrededor. No uses magenta dentro de los dibujos."
run(){ name=$1; shift; (codex exec --dangerously-bypass-approvals-and-sandbox --skip-git-repo-check "Usa tu herramienta de generación de imágenes. $* Al final imprime NOMBRE => RUTA COMPLETA de cada imagen generada (aunque no hayas podido copiarla)." < /dev/null > log17-$name.txt 2>&1; echo "DONE $name $?") & }
run bowl "$S $KEY Crea mixbowl2.png (cuadrada) en $D/ con UN SOLO objeto grande centrado: un tazón para mezclar de cerámica color crema con una franja rosa y corazoncitos, MUY ANCHO y bajito, visto desde ARRIBA en ángulo alto (como 60 grados) para que la boca redonda se vea como una elipse ANCHA y ALTA que ocupe la mitad de arriba del dibujo; el interior está VACÍO, liso, de color crema claro con un poco de sombra, sin nada adentro. Que el borde de la boca sea grueso y redondeado."
run table "$S Crea 2 imágenes en $D/: mixtable-wide.png (16:9) y mixtable-tall.png (9:16): vista DESDE ARRIBA (cenital) de una barra de cocina de pastelería tierna de madera clara con un mantel de cuadritos rosa y blanco, harina espolvoreada, un rodillo, cáscaras de huevo, fresas, un libro de recetas abierto y frascos pequeños SOLO en las orillas; el CENTRO completamente despejado y amplio (ahí irá un tazón grande). Luz cálida suave."
run kitchen "$S Vista desde arriba en 3/4 como los muebles de interior de Pokémon. $KEY Crea kitchen2.png (imagen ancha 16:9) en $D/ con EXACTAMENTE 6 muebles de cocina en 2 filas de 3, todos con el mismo estilo (madera blanca con detalles menta y rosa pastel) y pensados para ir pegados a la pared: 1) mueble bajo de cocina con cubierta de mármol, cajones y una alacena alta encima con puertitas (ancho de 2 lugares), 2) fregadero integrado en mueble bajo con llave y ventanita encima no, solo alacena encima, 3) estufa con horno integrado y campana encima, con una ollita, 4) refrigerador alto de dos puertas menta con imanes, 5) isla de cocina con dos banquitos redondos, 6) mesa de comedor rectangular de madera con 4 sillas y un florero."
wait
echo ALLDONE
